#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "arena_runtime.h"
static a0_arena_session *session;
#define A0_COMPILER_READ(t) ((void)(t),a0_runtime_read(session))
#define A0_COMPILER_WRITE(t,v) ((void)(t),a0_runtime_write(session,(v)))
#include "module.c"
#include "api.h"
static a0_io io,before;
static SERVICE_RESULT service;
static void die(const char*s){fprintf(stderr,"%s\n",s);exit(1);}
static void want(uint32_t n){uint32_t v=a0_runtime_read(session);if(v!=n){fprintf(stderr,"protocol %u/%u\n",v,n);exit(2);}}
static void send(uint32_t op,uint32_t n,const uint32_t*a){a0_runtime_write(session,op);a0_runtime_write(session,n);for(uint32_t i=0;i<n;i++)a0_runtime_write(session,a[i]);}
static void load(uint32_t h,uint32_t off,uint32_t n,uint32_t*page){uint32_t a[]={h,off,n};send(2,3,a);want(0);want(n);for(uint32_t i=0;i<n;i++)page[i]=a0_runtime_read(session);}
static uint32_t upload(const unsigned char*s,uint32_t n){if(!n)return 0;send(1,1,&n);want(0);want(1);uint32_t h=a0_runtime_read(session);for(uint32_t i=0;i<n;){uint32_t k=n-i>128?128:n-i,a[131]={h,i,k};for(uint32_t j=0;j<k;j++)a[j+3]=s[i+j];send(3,k+3,a);want(0);want(0);i+=k;}return h;}
static void out(FILE*f,uint32_t n){if(fwrite(&n,4,1,f)!=1)die("output");}
static void raw(FILE*f,const uint32_t*p,uint32_t n){for(uint32_t i=0;i<n;i++)out(f,p[i]);}
static void bytes(FILE*f,uint32_t h,uint32_t start,uint32_t len){out(f,len);for(uint32_t i=0;i<len;){uint32_t n=len-i>128?128:len-i,page[128];load(h,start+i,n,page);raw(f,page,n);i+=n;}}
static void vector(FILE*f,const uint32_t*p,uint32_t off){bytes(f,p[off],0,p[off+1]);}
static void snapshot(FILE*f,uint32_t h){out(f,h?1:0);if(h){uint32_t p[128];load(h,0,128,p);raw(f,p,128);}}
static void failure(LOWER_RESULT r,uint32_t code){if(r.f0!=code||r.f3!=&io)die("failure status/io");for(uint32_t i=0;i<16;i++)if(r.f1.e[i])die("failure context");for(uint32_t i=3;i<112;i++)if(r.f2.e[i])die("failure descriptor view");if(r.f2.e[0]!=code||r.f2.e[1]!=1093681731u||r.f2.e[2]!=1)die("failure header");}
static void controls(void){for(uint32_t code=1;code<=8;code++){PAGE bad=service.f3.f1;bad.e[0]=code;failure(a0_arena_backend_context(&io,bad),code);}const uint32_t offsets[]={93,96,98,101,104,107};for(uint32_t i=0;i<6;i++){PAGE bad=service.f3.f1;bad.e[offsets[i]]^=1;failure(a0_arena_backend_context(&io,bad),6);}PAGE ls={0};ls.e[94]=2;ls.e[120]=1;ls.e[41]=service.f2.e[6];ls.e[42]=service.f2.e[7];LOWER_RESULT good=a0_arena_backend_attach_link(&io,service.f1,service.f2,ls);if(good.f0||good.f3!=&io||good.f2.e[3]!=1||good.f2.e[15]!=2||!good.f2.e[5])die("attach valid");uint32_t p[128];load(good.f2.e[5],0,128,p);if(memcmp(p,ls.e,sizeof p))die("link snapshot");ls.e[41]++;failure(a0_arena_backend_attach_link(&io,service.f1,service.f2,ls),3);ls.e[41]--;ls.e[94]=1;failure(a0_arena_backend_attach_link(&io,service.f1,service.f2,ls),3);ls.e[94]=2;ls.e[0]=8;failure(a0_arena_backend_attach_link(&io,service.f1,service.f2,ls),8);}
int main(int argc,char**argv){if(argc!=7)die("source output quantum budget controls maxpumps");FILE*f=fopen(argv[1],"rb");if(!f)die("source open");if(fseek(f,0,SEEK_END))die("source seek");long size=ftell(f);if(size<0||(uint64_t)size>UINT32_MAX)die("source size");rewind(f);uint32_t n=(uint32_t)size;unsigned char*source=malloc((size_t)n+1);if(!source||fread(source,1,n,f)!=n)die("source read");fclose(f);uint32_t budget=(uint32_t)strtoul(argv[4],NULL,10);session=a0_arena_create(budget,0);if(!session)die("session");memset(&io,0xa5,sizeof io);memcpy(&before,&io,sizeof io);HELLO_RESULT hello=a0_arena_hello(&io);if(hello.f0||hello.f1!=&io)die("hello");uint32_t h=upload(source,n);service=a0_arena_backend_service_begin(&io,h,n);uint32_t quantum=(uint32_t)strtoul(argv[3],NULL,10),maxpumps=(uint32_t)strtoul(argv[6],NULL,10),pumps=0;while(!a0_arena_backend_service_done(service.f0)){if(pumps++==maxpumps)die("proof pump bound");service=a0_arena_backend_service_resume(service,quantum);}if(service.f3.f6!=&io)die("service IO");uint32_t status=a0_arena_backend_service_status(service.f0);if(status!=service.f0.e[0])die("service status");if(!status&&strtoul(argv[5],NULL,10))controls();f=fopen(argv[2],"wb");if(!f)die("output open");out(f,status);out(f,pumps);raw(f,service.f0.e,128);raw(f,service.f3.f0.e,128);raw(f,service.f3.f1.e,128);const uint32_t mo[]={32,35,38,41,44,47,50,53,56,59,62,68,71,74,97,100,103,106};for(uint32_t i=0;i<sizeof mo/sizeof mo[0];i++)vector(f,service.f3.f1.e,mo[i]);uint32_t symbols=service.f3.f1.e[67];out(f,symbols);for(uint32_t i=0;i<symbols;i++){uint32_t p[128];load(service.f3.f1.e[62],i*5,5,p);bytes(f,p[0],p[1],p[2]);}raw(f,service.f1.e,16);raw(f,service.f2.e,128);const uint32_t ds[]={16,19,22,25,28,31,34,37,40,43,46};for(uint32_t i=0;i<sizeof ds/sizeof ds[0];i++)vector(f,service.f2.e,ds[i]);snapshot(f,service.f2.e[4]);snapshot(f,service.f2.e[5]);uint32_t intact=1;for(uint32_t i=0;i<n;){uint32_t count=n-i>128?128:n-i,p[128];load(h,i,count,p);for(uint32_t j=0;j<count;j++)if(p[j]!=source[i+j])intact=0;i+=count;}out(f,intact);out(f,strtoul(argv[5],NULL,10)!=0&&!status);fclose(f);free(source);if(memcmp(&io,&before,sizeof io))die("IO bytes changed");uint32_t code=0;send(5,1,&code);want(0);want(0);if(!a0_arena_is_complete(session)||a0_arena_allocated_words(session)||a0_arena_protocol_failed(session))die("incomplete");a0_arena_destroy(session);return 0;}
